echo "K1: dpabs (install only, CPU)"; N=/workspace/nox; D=$N/ops/dpo; ts=$(date +%s); W=$(mktemp -d)
base64 -d > $W/rel_gates.py <<'B64'

B64
base64 -d > $W/stack_ab.py <<'B64'

B64
python3 -m py_compile $W/rel_gates.py $W/stack_ab.py || { echo PYFAIL; exit 0; }
cp -a $D/rel_gates.py $D/rel_gates.py.bak_abs_$ts; cp $W/rel_gates.py $D/rel_gates.py; cp $W/stack_ab.py $D/stack_ab.py
echo "installed abs=$(grep -c 'АБСОЛЮТНЫЕ' $D/rel_gates.py) stack_ab=$([ -f $D/stack_ab.py ] && echo 1 || echo 0)"
echo "state: pending=$([ -f $N/state/p3/dpo_pending ] && echo 1 || echo 0) hold_owner=$(ls $N/state/p3/dpo_pending.hold_owner 2>/dev/null | wc -l) pause_owner=$(ls $N/state/*dpo_pause_owner* $N/state/p3/*dpo_pause_owner* 2>/dev/null | wc -l) window_off=$([ -e $N/state/train_window.off ] && echo 1 || echo 0) trainer=$(pgrep -fc 'python -I train_dpo.py|rel_gates.py') 8104=$(curl -s -o /dev/null -m 5 -w %{http_code} http://127.0.0.1:8104/health)"
rm -rf $W; echo END
